     1|/**
     2| * IVX Direct Auth — GoTrue Bypass Endpoint
     3| *
     4| * When Supabase GoTrue (auth/v1) is degraded or unreachable (522/timeout),
     5| * this endpoint authenticates the owner by querying auth.users via a custom
     6| * RPC function, verifying the bcrypt password hash, and minting a
     7| * Supabase-compatible JWT using JWT_SECRET.
     8| *
     9| * Uses SUPABASE_SERVICE_ROLE_KEY + REST API — same pattern as durable store.
    10| * No SUPABASE_DB_URL or direct Postgres needed.
    11| *
    12| * Route: POST /api/ivx/auth/direct-sign-in
    13| * Body: { email, password }
    14| */
    15|import { ownerOnlyOptions } from './owner-only';
    16|
    17|const DEPLOYMENT_MARKER = 'ivx-direct-auth-gotrue-bypass-2026-08-05';
    18|
    19|// ── Env resolution ──────────────────────────────────────────────────────────
    20|
    21|const SERVICE_ROLE_NAMES = ['SUPABASE_SERVICE_ROLE_KEY', 'SUPABASE_SERVICE_KEY'] as const;
    22|const SUPABASE_URL_NAMES = ['EXPO_PUBLIC_SUPABASE_URL', 'SUPABASE_URL'] as const;
    23|
    24|function readTrimmed(value: unknown): string {
    25|  return typeof value === 'string' ? value.trim() : '';
    26|}
    27|
    28|function sanitizeEmail(raw: string): string {
    29|  return readTrimmed(raw).toLowerCase();
    30|}
    31|
    32|function getSupabaseUrl(): string {
    33|  for (const name of SUPABASE_URL_NAMES) {
    34|    const value = readTrimmed(process.env[name]).replace(/\/+$/, '');
    35|    if (value) return value;
    36|  }
    37|  return '';
    38|}
    39|
    40|function getServiceRoleKey(): string {
    41|  for (const name of SERVICE_ROLE_NAMES) {
    42|    const value = readTrimmed(process.env[name]);
    43|    if (value) return value;
    44|  }
    45|  return '';
    46|}
    47|
    48|function getSupabaseProjectRef(): string {
    49|  return getSupabaseUrl().match(/https:\/\/([a-z0-9]+)\.supabase\.co/i)?.[1] ?? 'kvclcdjmjghndxsngfzb';
    50|}
    51|
    52|function maskEmail(email: string): string {
    53|  if (!email || !email.includes('@')) return '(invalid)';
    54|  const [local, domain] = email.split('@');
    55|  if (!local || !domain) return '(invalid)';
    56|  const maskedLocal = local.length <= 2 ? local[0] + '***' : local.slice(0, 2) + '***';
    57|  return `${maskedLocal}@${domain}`;
    58|}
    59|
    60|function buildHeaders(): Record<string, string> {
    61|  const key = getServiceRoleKey();
    62|  return {
    63|    apikey: key,
    64|    Authorization: `Bearer ${key}`,
    65|    'Content-Type': 'application/json',
    66|  };
    67|}
    68|
    69|// ── Lazy module loading ─────────────────────────────────────────────────────
    70|
    71|let _bcryptModule: typeof import('bcryptjs') | null = null;
    72|async function getBcryptModule(): Promise<typeof import('bcryptjs')> {
    73|  if (_bcryptModule) return _bcryptModule;
    74|  _bcryptModule = await import('bcryptjs');
    75|  return _bcryptModule;
    76|}
    77|
    78|let _jwtModule: typeof import('jsonwebtoken') | null = null;
    79|async function getJwtModule(): Promise<typeof import('jsonwebtoken')> {
    80|  if (_jwtModule) return _jwtModule;
    81|  _jwtModule = await import('jsonwebtoken');
    82|  return _jwtModule;
    83|}
    84|
    85|// ── Types ───────────────────────────────────────────────────────────────────
    86|
    87|interface AuthUserRow {
    88|  id: string;
    89|  email: string;
    90|  encrypted_password: string;
    91|  email_confirmed_at: string | null;
    92|  raw_user_meta_data: Record<string, unknown> | null;
    93|  raw_app_meta_data: Record<string, unknown> | null;
    94|  aud: string;
    95|  role: string;
    96|  created_at: string;
    97|  updated_at: string;
    98|}
    99|
   100|// ── JWT minting ─────────────────────────────────────────────────────────────
   101|
   102|function mintAccessToken(jwt: typeof import('jsonwebtoken'), user: AuthUserRow, jwtSecret: string): string {
   103|  const now = Math.floor(Date.now() / 1000);
   104|  const expiresIn = 3600;
   105|  const projectRef = getSupabaseProjectRef();
   106|
   107|  const payload = {
   108|    iss: `https://${projectRef}.supabase.co/auth/v1/`,
   109|    sub: user.id,
   110|    aud: 'authenticated',
   111|    exp: now + expiresIn,
   112|    iat: now,
   113|    email: user.email,
   114|    phone: '',
   115|    app_metadata: user.raw_app_meta_data ?? {},
   116|    user_metadata: user.raw_user_meta_data ?? {},
   117|    role: 'authenticated',
   118|    aal: 'aal1',
   119|    amr: [{ method: 'password', timestamp: now }],
   120|    session_id: crypto.randomUUID(),
   121|    is_anonymous: false,
   122|  };
   123|
   124|  return jwt.sign(payload, jwtSecret, { algorithm: 'HS256', header: { alg: 'HS256', typ: 'JWT' } });
   125|}
   126|
   127|function mintRefreshToken(jwt: typeof import('jsonwebtoken'), user: AuthUserRow, jwtSecret: string): string {
   128|  const now = Math.floor(Date.now() / 1000);
   129|  const expiresIn = 86400 * 30;
   130|  const projectRef = getSupabaseProjectRef();
   131|
   132|  const payload = {
   133|    iss: `https://${projectRef}.supabase.co/auth/v1/`,
   134|    sub: user.id,
   135|    aud: 'authenticated',
   136|    exp: now + expiresIn,
   137|    iat: now,
   138|    session_id: crypto.randomUUID(),
   139|    refresh_token_aal: 'aal1',
   140|  };
   141|
   142|  return jwt.sign(payload, jwtSecret, { algorithm: 'HS256' });
   143|}
   144|
   145|// ── RPC function deployment + query ─────────────────────────────────────────
   146|
   147|/**
   148| * Single-statement SQL to create a function that queries auth.users by email.
   149| * This is a SINGLE statement so ivx_exec_sql's EXECUTE can handle it.
   150| * SECURITY DEFINER allows it to access the auth schema.
   151| */
   152|const CREATE_FUNCTION_SQL = `CREATE OR REPLACE FUNCTION public.ivx_query_auth_user_by_email(user_email TEXT) RETURNS JSON AS $fn$ BEGIN RETURN (SELECT json_build_object('id', u.id::text, 'email', u.email, 'encrypted_password', u.encrypted_password, 'email_confirmed_at', u.email_confirmed_at, 'raw_user_meta_data', u.raw_user_meta_data, 'raw_app_meta_data', u.raw_app_meta_data, 'aud', u.aud, 'role', u.role, 'created_at', u.created_at::text, 'updated_at', u.updated_at::text) FROM auth.users u WHERE u.email = user_email LIMIT 1); END; $fn$ LANGUAGE plpgsql SECURITY DEFINER`;
   153|
   154|let _functionDeployed = false;
   155|
   156|/** Deploy the query function via ivx_exec_sql (one-time, persists in DB). */
   157|async function ensureQueryFunction(): Promise<void> {
   158|  if (_functionDeployed) return;
   159|  const supabaseUrl = getSupabaseUrl();
   160|  const controller = new AbortController();
   161|  const timeout = setTimeout(() => controller.abort(), 15_000);
   162|  try {
   163|    const response = await fetch(`${supabaseUrl}/rest/v1/rpc/ivx_exec_sql`, {
   164|      method: 'POST',
   165|      headers: buildHeaders(),
   166|      body: JSON.stringify({ sql_text: CREATE_FUNCTION_SQL }),
   167|      signal: controller.signal,
   168|    });
   169|    if (response.ok) {
   170|      _functionDeployed = true;
   171|      console.log('[IVX Direct Auth] Query function deployed successfully');
   172|    } else {
   173|      const text = await response.text().catch(() => '');
   174|      // If function already exists, that's fine
   175|      if (text.includes('already exists') || response.status === 409 || response.ok) {
   176|        _functionDeployed = true;
   177|        console.log('[IVX Direct Auth] Query function already exists');
   178|      } else {
   179|        throw new Error(`Failed to deploy query function: HTTP ${response.status} ${text.slice(0, 300)}`);
   180|      }
   181|    }
   182|  } finally {
   183|    clearTimeout(timeout);
   184|  }
   185|}
   186|
   187|/** Query auth.users by email via the custom RPC function. */
   188|async function queryAuthUserByEmail(email: string): Promise<AuthUserRow | null> {
   189|  const supabaseUrl = getSupabaseUrl();
   190|
   191|  // Ensure the function exists (one-time, cached)
   192|  await ensureQueryFunction();
   193|
   194|  // Call the function via REST API
   195|  const controller = new AbortController();
   196|  const timeout = setTimeout(() => controller.abort(), 12_000);
   197|  try {
   198|    const response = await fetch(`${supabaseUrl}/rest/v1/rpc/ivx_query_auth_user_by_email`, {
   199|      method: 'POST',
   200|      headers: buildHeaders(),
   201|      body: JSON.stringify({ user_email: email }),
   202|      signal: controller.signal,
   203|    });
   204|
   205|    if (!response.ok) {
   206|      const text = await response.text().catch(() => '');
   207|      console.error(`[IVX Direct Auth] Query RPC failed: HTTP ${response.status} ${text.slice(0, 300)}`);
   208|      throw new Error(`Query RPC returned HTTP ${response.status}: ${text.slice(0, 200)}`);
   209|    }
   210|
   211|    const data = await response.json();
   212|    if (!data || typeof data !== 'object') {
   213|      return null;
   214|    }
   215|
   216|    const userRow = data as Record<string, unknown>;
   217|    if (!userRow.id) {
   218|      return null;
   219|    }
   220|
   221|    return {
   222|      id: String(userRow.id),
   223|      email: String(userRow.email ?? ''),
   224|      encrypted_password: String(userRow.encrypted_password ?? ''),
   225|      email_confirmed_at: userRow.email_confirmed_at ? String(userRow.email_confirmed_at) : null,
   226|      raw_user_meta_data: (userRow.raw_user_meta_data as Record<string, unknown>) ?? null,
   227|      raw_app_meta_data: (userRow.raw_app_meta_data as Record<string, unknown>) ?? null,
   228|      aud: String(userRow.aud ?? 'authenticated'),
   229|      role: String(userRow.role ?? 'authenticated'),
   230|      created_at: String(userRow.created_at ?? ''),
   231|      updated_at: String(userRow.updated_at ?? ''),
   232|    };
   233|  } finally {
   234|    clearTimeout(timeout);
   235|  }
   236|}
   237|
   238|// ── Main handler ────────────────────────────────────────────────────────────
   239|
   240|export function ivxDirectAuthOptions(): Response {
   241|  return ownerOnlyOptions();
   242|}
   243|
   244|export async function handleIVXDirectAuthSignIn(request: Request): Promise<Response> {
   245|  if (request.method !== 'POST') {
   246|    return Response.json(
   247|      { ok: false, error: 'Method not allowed.', deploymentMarker: DEPLOYMENT_MARKER },
   248|      { status: 405, headers: { 'Access-Control-Allow-Origin': '*' } },
   249|    );
   250|  }
   251|
   252|  let body: Record<string, unknown> = {};
   253|  try {
   254|    body = (await request.json().catch(() => ({}))) as Record<string, unknown>;
   255|  } catch {
   256|    body = {};
   257|  }
   258|
   259|  const email = sanitizeEmail(String(body.email ?? ''));
   260|  const password = String(body.password ?? '');
   261|
   262|  if (!email || !password) {
   263|    return Response.json(
   264|      { ok: false, error: 'Email and password are required.', deploymentMarker: DEPLOYMENT_MARKER },
   265|      { status: 400, headers: { 'Access-Control-Allow-Origin': '*' } },
   266|    );
   267|  }
   268|
   269|  const jwtSecret = readTrimmed(process.env.JWT_SECRET);
   270|  if (!jwtSecret) {
   271|    console.error('[IVX Direct Auth] JWT_SECRET is not configured.');
   272|    return Response.json(
   273|      { ok: false, error: 'Server is not configured for direct authentication.', errorCode: 'jwt_secret_missing', deploymentMarker: DEPLOYMENT_MARKER },
   274|      { status: 500, headers: { 'Access-Control-Allow-Origin': '*' } },
   275|    );
   276|  }
   277|
   278|  const supabaseUrl = getSupabaseUrl();
   279|  const serviceKey = getServiceRoleKey();
   280|  if (!supabaseUrl || !serviceKey) {
   281|    console.error('[IVX Direct Auth] Supabase URL or service role key not configured.');
   282|    return Response.json(
   283|      { ok: false, error: 'Server is not configured for direct authentication.', errorCode: 'supabase_not_configured', deploymentMarker: DEPLOYMENT_MARKER },
   284|      { status: 500, headers: { 'Access-Control-Allow-Origin': '*' } },
   285|    );
   286|  }
   287|
   288|  try {
   289|    // 1. Query auth.users via custom RPC function
   290|    const userRow = await queryAuthUserByEmail(email);
   291|
   292|    if (!userRow) {
   293|      console.log(`[IVX Direct Auth] No user found for email: ${maskEmail(email)}`);
   294|      return Response.json(
   295|        { ok: false, error: 'Invalid email or password.', deploymentMarker: DEPLOYMENT_MARKER },
   296|        { status: 401, headers: { 'Access-Control-Allow-Origin': '*' } },
   297|      );
   298|    }
   299|
   300|    // 2. Check email confirmed
   301|    if (!userRow.email_confirmed_at) {
   302|      console.log(`[IVX Direct Auth] Email not confirmed for: ${maskEmail(email)}`);
   303|      return Response.json(
   304|        { ok: false, error: 'Your email is not confirmed yet. Check your inbox for the confirmation link.', deploymentMarker: DEPLOYMENT_MARKER },
   305|        { status: 401, headers: { 'Access-Control-Allow-Origin': '*' } },
   306|      );
   307|    }
   308|
   309|    // 3. Verify password with bcrypt
   310|    const bcrypt = await getBcryptModule();
   311|    const storedHash = userRow.encrypted_password;
   312|    if (!storedHash) {
   313|      console.log(`[IVX Direct Auth] No password hash for user: ${maskEmail(email)}`);
   314|      return Response.json(
   315|        { ok: false, error: 'Invalid email or password.', deploymentMarker: DEPLOYMENT_MARKER },
   316|        { status: 401, headers: { 'Access-Control-Allow-Origin': '*' } },
   317|      );
   318|    }
   319|
   320|    const passwordValid = await bcrypt.compare(password, storedHash);
   321|    if (!passwordValid) {
   322|      console.log(`[IVX Direct Auth] Password verification failed for: ${maskEmail(email)}`);
   323|      return Response.json(
   324|        { ok: false, error: 'Invalid email or password.', deploymentMarker: DEPLOYMENT_MARKER },
   325|        { status: 401, headers: { 'Access-Control-Allow-Origin': '*' } },
   326|      );
   327|    }
   328|
   329|    // 4. Mint JWT tokens
   330|    const jwt = await getJwtModule();
   331|    const accessToken = mintAccessToken(jwt, userRow, jwtSecret);
   332|    const refreshToken = mintRefreshToken(jwt, userRow, jwtSecret);
   333|    const expiresAt = Math.floor(Date.now() / 1000) + 3600;
   334|
   335|    // 5. Build user object matching Supabase shape
   336|    const user = {
   337|      id: userRow.id,
   338|      aud: userRow.aud || 'authenticated',
   339|      role: userRow.role || 'authenticated',
   340|      email: userRow.email,
   341|      email_confirmed_at: userRow.email_confirmed_at,
   342|      created_at: userRow.created_at,
   343|      updated_at: userRow.updated_at,
   344|      app_metadata: userRow.raw_app_meta_data ?? {},
   345|      user_metadata: userRow.raw_user_meta_data ?? {},
   346|      is_anonymous: false,
   347|    };
   348|
   349|    console.log(`[IVX Direct Auth] Sign-in succeeded for: ${maskEmail(email)}, user_id: ${userRow.id}`);
   350|
   351|    return Response.json(
   352|      {
   353|        ok: true,
   354|        access_token: accessToken,
   355|        refresh_token: refreshToken,
   356|        expires_at: expiresAt,
   357|        expires_in: 3600,
   358|        token_type: 'bearer',
   359|        user,
   360|        deploymentMarker: DEPLOYMENT_MARKER,
   361|        timestamp: new Date().toISOString(),
   362|      },
   363|      { status: 200, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' } },
   364|    );
   365|  } catch (error) {
   366|    const message = error instanceof Error ? error.message : 'Unknown error during direct auth.';
   367|    console.error('[IVX Direct Auth] Error:', message);
   368|    let errorCode = 'unknown_error';
   369|    let safeMessage = 'Sign-in failed. Please try again or contact support.';
   370|    if (message.includes('timeout') || message.includes('aborted') || message.includes('AbortError')) {
   371|      errorCode = 'rest_timeout';
   372|      safeMessage = 'Authentication service is temporarily unavailable. Please try again.';
   373|    } else if (message.includes('Query RPC')) {
   374|      errorCode = 'query_rpc_failed';
   375|      safeMessage = 'Server could not query the auth database. Please try again.';
   376|    } else if (message.includes('query function') || message.includes('deploy')) {
   377|      errorCode = 'function_deploy_failed';
   378|      safeMessage = 'Server could not initialize the auth query. Please try again.';
   379|    } else if (message.includes('Cannot find module') || message.includes('MODULE_NOT_FOUND')) {
   380|      errorCode = 'module_not_found';
   381|      safeMessage = 'Server module loading error. Contact your administrator.';
   382|    } else if (message.includes('bcrypt')) {
   383|      errorCode = 'bcrypt_error';
   384|      safeMessage = 'Password verification error. Contact your administrator.';
   385|    }
   386|    return Response.json(
   387|      { ok: false, error: safeMessage, errorCode, deploymentMarker: DEPLOYMENT_MARKER },
   388|      { status: 503, headers: { 'Access-Control-Allow-Origin': '*' } },
   389|    );
   390|  }
