    24|import {
    25|  assertIVXRegisteredOwnerBearer,
    26|  ownerOnlyJson,
    27|  ownerOnlyOptions,
    28|} from './owner-only';
    29|
    30|function readEnv(name: string): string {
    31|  const v = process.env[name];
    32|  return typeof v === 'string' ? v.trim() : '';
    33|}
    34|
    35|function resolveSupabaseUrl(): string {
    36|  return readEnv('EXPO_PUBLIC_SUPABASE_URL') || readEnv('SUPABASE_URL');
    37|}
    38|
    39|function resolveSupabaseAnonKey(): string {
    40|  return readEnv('EXPO_PUBLIC_SUPABASE_ANON_KEY') || readEnv('SUPABASE_ANON_KEY');
    41|}
    42|
    43|function resolveSupabaseServiceRoleKey(): string {
    44|  return readEnv('SUPABASE_SERVICE_ROLE_KEY') || readEnv('SUPABASE_SERVICE_KEY');
    45|}
    46|
