    48|  'Content-Type': 'application/json',
    49|  'Cache-Control': 'no-store',
    50|  'Access-Control-Allow-Origin': 'https://ivxholding.com',
    51|  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    52|  'Access-Control-Allow-Methods': 'POST, OPTIONS',
